class Solution {
public:
    std::vector<int> transformArray(std::vector<int>& arr) {
        bool changed = true;
        while (changed) {
            changed = false;
            std::vector<int> nxt = arr;
            for (int i = 1; i < arr.size() - 1; ++i) {
                if (arr[i] < arr[i - 1] && arr[i] < arr[i + 1]) {
                    nxt[i]++;
                    changed = true;
                } else if (arr[i] > arr[i - 1] && arr[i] > arr[i + 1]) {
                    nxt[i]--;
                    changed = true;
                }
            }
            arr = std::move(nxt);
        }
        return arr;
    }
};

class Solution {
    public java.util.List<Integer> transformArray(int[] arr) {
        boolean changed = true;
        while (changed) {
            changed = false;
            int[] nxt = arr.clone();
            for (int i = 1; i < arr.length - 1; i++) {
                if (arr[i] < arr[i - 1] && arr[i] < arr[i + 1]) {
                    nxt[i]++;
                    changed = true;
                } else if (arr[i] > arr[i - 1] && arr[i] > arr[i + 1]) {
                    nxt[i]--;
                    changed = true;
                }
            }
            arr = nxt;
        }
        java.util.List<Integer> res = new java.util.ArrayList<>();
        for (int x : arr) res.add(x);
        return res;
    }
}

